			function getGroup(QESITM_SQNCE){
			    var idx = app.lookup('qustnbList').getRowCount();
			    var grp;
			    for(var i=0;i<idx;i++){
			        var obj = app.lookup('qustnbList').getRowData(i);
			        if((QESITM_SQNCE-0) >= (obj.QUSTNB_BGNG_QESITM_NO-0) && QESITM_SQNCE <= (obj.QUSTNB_END_QESITM_NO-0)){
			            grp = obj.QUSTNB_RELM_ESNTAL_NM;
			            break;
			        }
			    }
			    return grp;
			}

